mapper.select:
SELECT ec.expense_category_id AS category_id, ec.category_name,
       COALESCE(SUM(t.amount), 0) AS current_expense
FROM expense_category ec
LEFT JOIN `transaction` t
    ON t.expense_category_id = ec.expense_category_id
    AND t.user_id = #{userId}
    AND t.transaction_type = 'PAYMENT'
    AND t.transacted_at >= #{startDateTime}
    AND t.transacted_at < #{endDateTime}
WHERE ec.expense_category_id IN
  #{categoryId}
GROUP BY ec.expense_category_id, ec.category_name
ORDER BY current_expense DESC, ec.expense_category_id ASC
